import { constants } from "node:fs";

import { accessWrapper } from "../access/wrapper";

/**
 * @name fileIsVisible
 * @description File is visible to the calling process
 * @since 0.0.5
 * @async
 * @param {string|Buffer|URL} pathToFile
 * @returns {Promise<boolean|Error>}
 */
export async function fileIsVisible(pathToFile: string | Buffer | URL): Promise<boolean | Error> {
	return accessWrapper(constants.F_OK, pathToFile);
}
